"""Compiler-owned source declarations shared by the structural scanners."""

import re

_PROTOC_GEN_ES_HEADER = re.compile(
    r'// @generated by protoc-gen-(?:connect-)?es v\d+\.\d+\.\d+(?: with parameter "[^\n"]+")?'
)
_PROTOC_GEN_ES_SOURCE = re.compile(
    r"// @generated from file \S+\.proto \((?:package [^,\s)]+, )?(?:syntax proto[23]|edition [^)]+)\)"
)


def compiler_generated(text):
    # A generated filename alone does not exempt authored embedded policy or
    # bundled code. These headers identify reproducible protocol compiler output.
    comments = []
    for line in text[:512].splitlines():
        line = line.strip()
        if not line:
            continue
        if not line.startswith(("//", "#")):
            break
        comments.append(line)
    header = "\n".join(comments)
    return ("Generated by the protocol buffer compiler." in header and "DO NOT EDIT" in header
            or "automatically generated by the FlatBuffers compiler" in header and "do not modify" in header.lower()
            or "// @generated by buffa-codegen. DO NOT EDIT." in comments
            or "// @generated by connectrpc-build. DO NOT EDIT." in comments
            or "// @generated by connectrpc-codegen. DO NOT EDIT." in comments
            or any(_PROTOC_GEN_ES_HEADER.fullmatch(a) and _PROTOC_GEN_ES_SOURCE.fullmatch(b)
                   for a, b in zip(comments, comments[1:])))
